public long[] rangeSum(int[] A, int[][] B) {
    int N = A.length;
    long[] prefix = new long[N];
    prefix[0] = A[0];
    for (int i = 1; i < N; i++) {
        prefix[i] = prefix[i - 1] + A[i];
    }

    long[] result = new long[B.length];
    for (int q = 0; q < B.length; q++) {
        int L = B[q][0];
        int R = B[q][1];
        long sum;
        if (L == 0) {
            sum = prefix[R];
        } else {
            sum = prefix[R] - prefix[L - 1];
        }
        result[q] = sum;
    }
    return result;
}

public int specialIndexBrute(int[] A) {
