public int pickFromBothSides(int[] A, int B) {
    int N = A.length;
    int sum = 0;
    for (int i = 0; i < B; i++) {
        sum += A[i];
    }
    int best = sum;
    for (int k = 0; k < B; k++) {
        sum = sum - A[B - 1 - k] + A[N - 1 - k];
        if (sum > best) {
            best = sum;
        }
    }
    return best;
}

