public int maxProfit(int[] A) {
    if (A.length == 0) {
        return 0;
    }
    int minSoFar = A[0];
    int best = 0;
    for (int i = 1; i < A.length; i++) {
        if (A[i] - minSoFar > best) {
            best = A[i] - minSoFar;
        }
        if (A[i] < minSoFar) {
            minSoFar = A[i];
        }
    }
    return best;
}

