// Pattern A — Count subarrays with sum == K (handles negatives)
public int countSumEqualsK(int[] A, int K) {
    Map<Long, Integer> seen = new HashMap<>();
    seen.put(0L, 1);
    long sum = 0;
    int count = 0;
    for (int x : A) {
        sum += x;
        count += seen.getOrDefault(sum - K, 0);
        seen.merge(sum, 1, Integer::sum);
    }
    return count;
}

// Pattern B — Longest subarray with sum == K (handles negatives)
public int longestSumEqualsK(int[] A, int K) {
    Map<Long, Integer> first = new HashMap<>();
    first.put(0L, -1);
    long sum = 0;
    int best = 0;
    for (int i = 0; i < A.length; i++) {
        sum += A[i];
        if (first.containsKey(sum - K)) {
            best = Math.max(best, i - first.get(sum - K));
        }
        first.putIfAbsent(sum, i);
    }
    return best;
}

