public int countSumAtMostK(int[] A, int K) {
    int left = 0;
    long sum = 0;
    int count = 0;
    for (int right = 0; right < A.length; right++) {
        sum += A[right];
        while (sum > K && left <= right) {
            sum -= A[left];
            left++;
        }
        count += (right - left + 1);
    }
    return count;
}

// Pattern D — Longest subarray with sum <= K (positives only)
public int longestSumAtMostK(int[] A, int K) {
    int left = 0;
    long sum = 0;
    int best = 0;
    for (int right = 0; right < A.length; right++) {
        sum += A[right];
        while (sum > K && left <= right) {
            sum -= A[left];
            left++;
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

// Pattern E — Count subarrays with sum == K (positives only) via atMost(K) - atMost(K-1)
public int countSumEqualsKPositive(int[] A, int K) {
    return countSumAtMostK(A, K) - countSumAtMostK(A, K - 1);
