// Pattern F — Longest subarray with at-most K distinct elements
public int longestAtMostKDistinct(int[] A, int K) {
    Map<Integer, Integer> freq = new HashMap<>();
    int left = 0;
    int best = 0;
    for (int right = 0; right < A.length; right++) {
        freq.merge(A[right], 1, Integer::sum);
        while (freq.size() > K) {
            int c = freq.get(A[left]) - 1;
            if (c == 0) {
                freq.remove(A[left]);
            } else {
                freq.put(A[left], c);
            }
            left++;
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

// Pattern G — Count subarrays with EXACTLY K distinct = atMost(K) - atMost(K-1)
public int countExactlyKDistinct(int[] A, int K) {
    return countAtMostKDistinct(A, K) - countAtMostKDistinct(A, K - 1);
}
private int countAtMostKDistinct(int[] A, int K) {
    if (K < 0) {
        return 0;
    }
    Map<Integer, Integer> freq = new HashMap<>();
    int left = 0;
    int count = 0;
    for (int right = 0; right < A.length; right++) {
        freq.merge(A[right], 1, Integer::sum);
        while (freq.size() > K) {
            int c = freq.get(A[left]) - 1;
            if (c == 0) {
                freq.remove(A[left]);
            } else {
                freq.put(A[left], c);
            }
            left++;
        }
        count += (right - left + 1);
    }
    return count;
}

