// Pattern I — Count subarrays with sum <= K (handles negatives)
public long countSumAtMostKAnySign(int[] A, long K) {
    int N = A.length;
    long[] P = new long[N + 1];
    for (int i = 0; i < N; i++) {
        P[i + 1] = P[i] + A[i];
    }
    return mergeCount(P, 0, N, K, new long[N + 1]);
}
private long mergeCount(long[] P, int lo, int hi, long K, long[] buf) {
    if (hi - lo <= 1) {
        return 0;
    }
    int mid = lo + (hi - lo) / 2;
    long count = mergeCount(P, lo, mid, K, buf) + mergeCount(P, mid, hi, K, buf);
    // count pairs (i, j) with lo <= i < mid <= j < hi and P[j] - P[i] <= K
    int j = mid;
    int valid = mid;
    for (int i = lo; i < mid; i++) {
        while (valid < hi && P[valid] - P[i] <= K) {
            valid++;
        }
        count += (valid - mid);
    }
    // standard merge into buf and copy back
    int p = lo;
    int q = mid;
    int k = lo;
    while (p < mid && q < hi) {
        if (P[p] <= P[q]) {
            buf[k++] = P[p++];
        } else {
            buf[k++] = P[q++];
        }
    }
    while (p < mid) {
        buf[k++] = P[p++];
    }
    while (q < hi) {
        buf[k++] = P[q++];
    }
    for (int t = lo; t < hi; t++) {
        P[t] = buf[t];
    }
    return count;
}

// Pattern J — Kadane (max subarray sum, mixed signs) — sliding-window's specialisation
public int kadane(int[] A) {
    int currSum = 0;
    int best = Integer.MIN_VALUE;
    for (int x : A) {
        currSum += x;
        if (currSum > best) {
            best = currSum;
        }
        if (currSum < 0) {
            currSum = 0;
        }
    }
    return best;
}

