public int[][] antiDiagonals(int[][] A) {
    int N = A.length;
    int[][] out = new int[2 * N - 1][N];
    int rowIdx = 0;
    for (int j = 0; j < N; j++) {
        int r = 0;
        int c = j;
        int k = 0;
        while (r < N && c >= 0) {
            out[rowIdx][k] = A[r][c];
            r++;
            c--;
            k++;
        }
        rowIdx++;
    }
    for (int i = 1; i < N; i++) {
        int r = i;
        int c = N - 1;
        int k = 0;
        while (r < N && c >= 0) {
            out[rowIdx][k] = A[r][c];
            r++;
            c--;
            k++;
        }
        rowIdx++;
    }
    return out;
}

public int[][] transpose(int[][] A) {
    int R = A.length;
    int C = A[0].length;
    int[][] result = new int[C][R];
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            result[j][i] = A[i][j];
        }
    }
    return result;
}

public void rotate(int[][] A) {
    int N = A.length;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            int t = A[i][j];
            A[i][j] = A[j][i];
            A[j][i] = t;
        }
    }
    for (int i = 0; i < N; i++) {
        int l = 0;
        int r = N - 1;
        while (l < r) {
            int t = A[i][l];
            A[i][l] = A[i][r];
            A[i][r] = t;
            l++;
            r--;
        }
    }
}
